const SINIFLAR = ["1. Sınıf","2. Sınıf","3. Sınıf","4. Sınıf","5. Sınıf"];
const GROUPS = ["Grup A","Grup B","Grup C","Grup D","Grup E","Grup F","Grup G","Grup H"];

// ── Ders Programı Google Sheets ID'leri ──
const SCHEDULE_SHEETS = {
  "1. Sınıf": "1Xwqz2bXHvH2oQ_utv_WIVzPFvLZyJEXHvwey-bVDt7A",
  "2. Sınıf": "",
  "3. Sınıf": "",
};

// ── Uygulama Ders Programı Google Sheets ID'leri ──
const PRACTICE_SCHEDULE_SHEETS = {
  "1. Sınıf": "1N-FQBRdcvWUMlu5BtZ7EqXqUFRuGLFFvYGmT4ZCEwnA",
  "2. Sınıf": "",
  "3. Sınıf": "",
};

const TR_MONTHS = { "ocak":0,"şubat":1,"mart":2,"nisan":3,"mayıs":4,"haziran":5,"temmuz":6,"ağustos":7,"eylül":8,"ekim":9,"kasım":10,"aralık":11 };
const TR_MONTH_NAMES = ["Oca","Şub","Mar","Nis","May","Haz","Tem","Ağu","Eyl","Eki","Kas","Ara"];
const TR_MONTH_FULL = ["Ocak","Şubat","Mart","Nisan","Mayıs","Haziran","Temmuz","Ağustos","Eylül","Ekim","Kasım","Aralık"];
const TR_DAY_NAMES = ["Pazar","Pazartesi","Salı","Çarşamba","Perşembe","Cuma","Cumartesi"];
const TR_WEEKDAYS = { "pazartesi":1,"salı":2,"çarşamba":3,"perşembe":4,"cuma":5,"cumartesi":6,"pazar":0 };

const DILIM_COLORS = {
  "TIBBA MERHABA": "#00d4aa",
  "YAŞAMIN MOLEKÜLER TEMELLERİ": "#7c5cfc",
  "HÜCRE": "#0891b2",
  "DOKU": "#059669",
  "HAYATIN EVRELERİ": "#ffb03a",
  "HAREKET": "#ff5252",
  "DİKEY KORİDOR": "#f472b6",
  "SİNİR DUYU": "#0ea5e9",
  "PATOLOJİ": "#6366f1",
  "ÜROGENİTAL": "#8b5cf6",
};

function getDilimColor(dilim) {
  if (!dilim) return "#64748b";
  const d = dilim.toUpperCase();
  for (const [key, color] of Object.entries(DILIM_COLORS)) {
    if (d.includes(key)) return color;
  }
  // hash-based fallback
  let h = 0;
  for (let i = 0; i < d.length; i++) h = d.charCodeAt(i) + ((h << 5) - h);
  return `hsl(${Math.abs(h) % 360}, 55%, 55%)`;
}

function parseTurkishDate(str) {
  if (!str || typeof str !== "string") return null;
  str = str.trim();
  if (str.toUpperCase().startsWith("HER HAFTA")) return null;
  const parts = str.split(/\s+/);
  if (parts.length < 3) return null;
  const day = parseInt(parts[0]);
  const monthName = parts[1].toLowerCase();
  const year = parseInt(parts[2]);
  const month = TR_MONTHS[monthName];
  if (isNaN(day) || month === undefined || isNaN(year)) return null;
  return new Date(year, month, day);
}

function parseTime(str) {
  if (!str) return null;
  str = str.trim().replace(".", ":");
  const p = str.split(":");
  if (p.length !== 2) return null;
  const h = parseInt(p[0]), m = parseInt(p[1]);
  if (isNaN(h) || isNaN(m)) return null;
  return { h, m };
}

function getMonday(d) {
  const dt = new Date(d);
  const day = dt.getDay();
  const diff = dt.getDate() - day + (day === 0 ? -6 : 1);
  return new Date(dt.getFullYear(), dt.getMonth(), diff);
}

function isSameDay(a, b) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

function WeeklySchedule({ userYear, s }) {
  const [events, setEvents] = useState([]);
  const [recurringEvents, setRecurringEvents] = useState([]);
  const [weekStart, setWeekStart] = useState(getMonday(new Date()));
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [semesterRange, setSemesterRange] = useState({ start: null, end: null });
  const [selectedEvent, setSelectedEvent] = useState(null);

  useEffect(() => {
    const sheetId = SCHEDULE_SHEETS[userYear];
    if (!sheetId) {
      setError("Bu sınıf için ders programı henüz eklenmedi.");
      setLoading(false);
      return;
    }
    setLoading(true);
    setError(null);
    fetch(`https://docs.google.com/spreadsheets/d/${sheetId}/export?format=csv`)
      .then(r => r.text())
      .then(csv => {
        const lines = csv.split("\n");
        if (lines.length < 2) { setError("Tablo boş."); setLoading(false); return; }
        const parsed = [];
        const recurring = [];
        let minDate = null, maxDate = null;
        // Simple CSV parse
        for (let i = 1; i < lines.length; i++) {
          const row = [];
          let cur = "", inQ = false;
          for (const ch of lines[i]) {
            if (ch === '"') { inQ = !inQ; }
            else if (ch === ',' && !inQ) { row.push(cur.trim()); cur = ""; }
            else { cur += ch; }
          }
          row.push(cur.trim());
          const tarih = (row[1] || "").trim();
          const baslama = (row[2] || "").trim();
          const bitis = (row[3] || "").trim();
          const konu = (row[4] || "").trim();
          const dilim = (row[5] || "").trim();
          const yer = (row[6] || "").trim();
          if (!konu || konu.toUpperCase().includes("SERBEST ÇALIŞMA")) continue;
          const startT = parseTime(baslama);
          const endT = parseTime(bitis);
          // Clean subject
          let title = konu.replace(/^\d+\s*[-–]\s*/, "");
          let lecturer = "";
          const slashIdx = title.indexOf(" / ");
          if (slashIdx > -1) { lecturer = title.substring(slashIdx + 3).trim(); title = title.substring(0, slashIdx).trim(); }
          const evt = { title, lecturer, dilim, yer, startT, endT, konu };
          if (tarih.toUpperCase().startsWith("HER HAFTA")) {
            const dayName = tarih.replace(/HER HAFTA/i, "").trim().toLowerCase();
            const dayNum = TR_WEEKDAYS[dayName];
            if (dayNum !== undefined) recurring.push({ ...evt, dayOfWeek: dayNum });
          } else {
            const date = parseTurkishDate(tarih);
            if (date) {
              if (!minDate || date < minDate) minDate = date;
              if (!maxDate || date > maxDate) maxDate = date;
              parsed.push({ ...evt, date });
            }
          }
        }
        setEvents(parsed);
        setRecurringEvents(recurring);
        setSemesterRange({ start: minDate, end: maxDate });
        setLoading(false);
      })
      .catch(e => { setError("Veri yüklenemedi: " + e.message); setLoading(false); });
  }, [userYear]);

  const weekDays = [];
  for (let i = 0; i < 5; i++) {
    const d = new Date(weekStart);
    d.setDate(d.getDate() + i);
    weekDays.push(d);
  }

  const today = new Date();
  const todayMonday = getMonday(today);
  const isCurrentWeek = isSameDay(weekStart, todayMonday);

  // Calculate week number relative to semester start
  let weekNum = null;
  if (semesterRange.start) {
    const semesterMonday = getMonday(semesterRange.start);
    const diff = Math.floor((weekStart - semesterMonday) / (7 * 24 * 60 * 60 * 1000));
    if (diff >= 0) weekNum = diff + 1;
  }

  function getEventsForDay(date) {
    const dayEvents = events.filter(e => isSameDay(e.date, date));
    // Add recurring events
    const dow = date.getDay();
    const { start, end } = semesterRange;
    if (start && end && date >= start && date <= end) {
      for (const re of recurringEvents) {
        if (re.dayOfWeek === dow) dayEvents.push({ ...re, date });
      }
    }
    // Sort by start time
    dayEvents.sort((a, b) => {
      if (!a.startT || !b.startT) return 0;
      return (a.startT.h * 60 + a.startT.m) - (b.startT.h * 60 + b.startT.m);
    });
    return dayEvents;
  }

  const prevWeek = () => { const d = new Date(weekStart); d.setDate(d.getDate() - 7); setWeekStart(d); };
  const nextWeek = () => { const d = new Date(weekStart); d.setDate(d.getDate() + 7); setWeekStart(d); };
  const goToday = () => setWeekStart(getMonday(new Date()));

  const formatRange = () => {
    const end = new Date(weekStart); end.setDate(end.getDate() + 4);
    if (weekStart.getMonth() === end.getMonth()) {
      return `${weekStart.getDate()} – ${end.getDate()} ${TR_MONTH_FULL[weekStart.getMonth()]} ${weekStart.getFullYear()}`;
    }
    return `${weekStart.getDate()} ${TR_MONTH_NAMES[weekStart.getMonth()]} – ${end.getDate()} ${TR_MONTH_NAMES[end.getMonth()]} ${end.getFullYear()}`;
  };

  if (loading) return (
    <div style={{ textAlign:"center", padding:60 }}>
      <div style={{ fontSize:32, marginBottom:16, animation:"spin 1s linear infinite" }}>⏳</div>
      <p style={{ color:"#94a3b8", fontSize:14 }}>Ders programı yükleniyor...</p>
      <style>{`@keyframes spin { from { transform:rotate(0deg) } to { transform:rotate(360deg) } }`}</style>
    </div>
  );
  if (error) return (
    <div style={{ ...s.card, textAlign:"center", padding:40 }}>
      <div style={{ fontSize:40, marginBottom:12 }}>📭</div>
      <p style={{ color:"#f87171", fontSize:15, fontWeight:600 }}>{error}</p>
    </div>
  );

  return (
    <div>
      <p style={s.title}>📅 Ders Programı</p>
      {/* Week nav header */}
      <div style={{ ...s.card, display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:20, padding:"14px 20px", flexWrap:"wrap", gap:10 }}>
        <button onClick={prevWeek} style={{ ...s.btn(false), padding:"8px 14px", fontSize:18, lineHeight:1, cursor:"pointer" }} title="Önceki Hafta">◀</button>
        <div style={{ textAlign:"center", flex:1, minWidth:200 }}>
          <div style={{ fontSize:16, fontWeight:700, color:"#e8edf5" }}>{formatRange()}</div>
          {weekNum && <div style={{ fontSize:12, color:"#94a3b8", marginTop:2 }}>Hafta {weekNum}</div>}
        </div>
        <div style={{ display:"flex", gap:8 }}>
          {!isCurrentWeek && <button onClick={goToday} style={{ ...s.btn(true), padding:"8px 14px", fontSize:12 }}>Bugün</button>}
          <button onClick={nextWeek} style={{ ...s.btn(false), padding:"8px 14px", fontSize:18, lineHeight:1, cursor:"pointer" }} title="Sonraki Hafta">▶</button>
        </div>
      </div>

      {/* Weekly grid */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(5, 1fr)", gap:10 }}>
        {weekDays.map((day, di) => {
          const isToday = isSameDay(day, today);
          const dayEvents = getEventsForDay(day);
          return (
            <div key={di} style={{ minWidth:0 }}>
              {/* Day header */}
              <div style={{
                textAlign:"center", padding:"10px 4px", marginBottom:8, borderRadius:12,
                background: isToday ? "linear-gradient(135deg,rgba(0,212,170,0.2),rgba(0,184,148,0.1))" : "rgba(16,24,44,0.5)",
                border: isToday ? "1px solid rgba(0,212,170,0.4)" : "1px solid rgba(148,163,184,0.08)",
              }}>
                <div style={{ fontSize:13, fontWeight:600, color: isToday ? "#00d4aa" : "#94a3b8" }}>
                  {TR_DAY_NAMES[day.getDay()]}
                </div>
                <div style={{ fontSize:20, fontWeight:700, color: isToday ? "#00d4aa" : "#e8edf5", lineHeight:1.3 }}>
                  {day.getDate()}
                </div>
                <div style={{ fontSize:11, color: isToday ? "#00d4aa" : "#64748b" }}>
                  {TR_MONTH_NAMES[day.getMonth()]}
                </div>
              </div>
              {/* Events */}
              {dayEvents.length === 0 && (
                <div style={{ textAlign:"center", padding:"24px 8px", color:"#475569", fontSize:12, borderRadius:10, border:"1px dashed rgba(148,163,184,0.1)" }}>
                  Ders yok
                </div>
              )}
              {dayEvents.map((evt, ei) => {
                const color = getDilimColor(evt.dilim);
                const timeStr = evt.startT && evt.endT
                  ? `${String(evt.startT.h).padStart(2,"0")}:${String(evt.startT.m).padStart(2,"0")} – ${String(evt.endT.h).padStart(2,"0")}:${String(evt.endT.m).padStart(2,"0")}`
                  : "Tüm gün";
                // Short dilim label
                let dilimShort = evt.dilim || "";
                const slashI = dilimShort.indexOf(" / ");
                if (slashI > -1) dilimShort = dilimShort.substring(0, slashI);
                if (dilimShort.length > 22) dilimShort = dilimShort.substring(0, 20) + "…";
                // Short lecturer
                let lecShort = evt.lecturer || "";
                // Remove parenthetical
                lecShort = lecShort.replace(/\(.*?\)/g, "").trim();
                if (lecShort.length > 28) lecShort = lecShort.substring(0, 26) + "…";
                return (
                  <div key={ei} onClick={() => setSelectedEvent({ ...evt, timeStr, color, dilimShort })} style={{
                    marginBottom:6, borderRadius:10, padding:"8px 10px",
                    background:"rgba(16,24,44,0.7)",
                    borderLeft:`3px solid ${color}`,
                    border:`1px solid rgba(148,163,184,0.08)`,
                    borderLeftWidth:3, borderLeftColor:color, borderLeftStyle:"solid",
                    transition:"all 0.2s ease",
                    cursor:"pointer",
                    fontSize:12,
                  }}>
                    <div style={{ color:"#64748b", fontSize:10, marginBottom:3, fontWeight:600 }}>{timeStr}</div>
                    <div style={{ fontWeight:600, color:"#e8edf5", fontSize:12, lineHeight:1.3, marginBottom:4, wordBreak:"break-word" }}>
                      {evt.title.length > 50 ? evt.title.substring(0, 48) + "…" : evt.title}
                    </div>
                    {dilimShort && (
                      <div style={{ display:"inline-block", padding:"1px 7px", borderRadius:6, fontSize:9, fontWeight:700, background:`${color}22`, color, marginBottom:3 }}>
                        {dilimShort}
                      </div>
                    )}
                    {lecShort && (
                      <div style={{ color:"#94a3b8", fontSize:10, marginTop:2 }}>👨🏫 {lecShort}</div>
                    )}
                    {evt.yer && !evt.yer.toUpperCase().includes("BAKINIZ") && (
                      <div style={{ color:"#64748b", fontSize:10, marginTop:1 }}>📍 {evt.yer}</div>
                    )}
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>

      {/* Mobile: responsive stacking note */}
      <style>{`
        @media (max-width: 768px) {
          div[style*="grid-template-columns: repeat(5"] {
            grid-template-columns: 1fr !important;
          }
        }
      `}</style>

      {/* Event Detail Modal */}
      {selectedEvent && (
        <div onClick={() => setSelectedEvent(null)} style={{
          position:"fixed", inset:0, zIndex:9999,
          background:"rgba(0,0,0,0.7)", backdropFilter:"blur(6px)",
          display:"flex", alignItems:"center", justifyContent:"center",
          padding:20,
        }}>
          <div onClick={e => e.stopPropagation()} style={{
            background:"linear-gradient(145deg, #1a2340, #0f172a)",
            borderRadius:16, padding:24, maxWidth:420, width:"100%",
            border:`1px solid ${selectedEvent.color}33`,
            boxShadow:`0 20px 60px rgba(0,0,0,0.5), 0 0 40px ${selectedEvent.color}15`,
            position:"relative",
          }}>
            {/* Close button */}
            <button onClick={() => setSelectedEvent(null)} style={{
              position:"absolute", top:12, right:12, background:"rgba(148,163,184,0.1)",
              border:"none", color:"#94a3b8", fontSize:18, width:32, height:32,
              borderRadius:8, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center",
            }}>✕</button>

            {/* Time */}
            <div style={{ color:selectedEvent.color, fontSize:14, fontWeight:600, marginBottom:12 }}>
              🕐 {selectedEvent.timeStr}
            </div>

            {/* Full title */}
            <div style={{ fontWeight:700, color:"#e8edf5", fontSize:18, lineHeight:1.4, marginBottom:16, paddingRight:30 }}>
              {selectedEvent.title}
            </div>

            {/* Dilim */}
            {selectedEvent.dilim && (
              <div style={{ marginBottom:12 }}>
                <div style={{ color:"#64748b", fontSize:11, marginBottom:4, textTransform:"uppercase", letterSpacing:1 }}>Dilim</div>
                <div style={{
                  display:"inline-block", padding:"4px 12px", borderRadius:8, fontSize:13, fontWeight:700,
                  background:`${selectedEvent.color}22`, color:selectedEvent.color,
                }}>
                  {selectedEvent.dilim}
                </div>
              </div>
            )}

            {/* Lecturer */}
            {selectedEvent.lecturer && (
              <div style={{ marginBottom:12 }}>
                <div style={{ color:"#64748b", fontSize:11, marginBottom:4, textTransform:"uppercase", letterSpacing:1 }}>Öğretim Üyesi</div>
                <div style={{ color:"#e8edf5", fontSize:14 }}>👨🏫 {selectedEvent.lecturer}</div>
              </div>
            )}

            {/* Location */}
            {selectedEvent.yer && !selectedEvent.yer.toUpperCase().includes("BAKINIZ") && (
              <div style={{ marginBottom:12 }}>
                <div style={{ color:"#64748b", fontSize:11, marginBottom:4, textTransform:"uppercase", letterSpacing:1 }}>Yer</div>
                <div style={{ color:"#e8edf5", fontSize:14 }}>📍 {selectedEvent.yer}</div>
              </div>
            )}

            {/* Original konu */}
            {selectedEvent.konu && selectedEvent.konu !== selectedEvent.title && (
              <div style={{ marginTop:8, padding:"10px 14px", borderRadius:10, background:"rgba(148,163,184,0.06)", border:"1px solid rgba(148,163,184,0.08)" }}>
                <div style={{ color:"#64748b", fontSize:11, marginBottom:4, textTransform:"uppercase", letterSpacing:1 }}>Orijinal Kayıt</div>
                <div style={{ color:"#94a3b8", fontSize:13, lineHeight:1.5 }}>{selectedEvent.konu}</div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

function PracticeSchedule({ userYear, userGroup, s }) {
  const [events, setEvents] = useState([]);
  const [weekStart, setWeekStart] = useState(getMonday(new Date()));
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [semesterRange, setSemesterRange] = useState({ start: null, end: null });
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [filterGroup, setFilterGroup] = useState(userGroup || "Tüm Gruplar");

  useEffect(() => {
    const sheetId = PRACTICE_SCHEDULE_SHEETS[userYear];
    if (!sheetId) {
      setError("Bu sınıf için uygulama programı henüz eklenmedi.");
      setLoading(false);
      return;
    }
    setLoading(true);
    setError(null);
    fetch(`https://docs.google.com/spreadsheets/d/${sheetId}/export?format=csv`)
      .then(r => r.text())
      .then(csv => {
        const lines = csv.split("\n");
        if (lines.length < 2) { setError("Tablo boş."); setLoading(false); return; }
        const parsed = [];
        let currentDilim = "";
        let headers = [];
        let minDate = null, maxDate = null;
        
        for (let i = 0; i < lines.length; i++) {
          const row = [];
          let cur = "", inQ = false;
          for (const ch of lines[i]) {
            if (ch === '"') { inQ = !inQ; }
            else if (ch === ',' && !inQ) { row.push(cur.trim()); cur = ""; }
            else { cur += ch; }
          }
          row.push(cur.trim());
          
          const c0 = (row[0] || "").toUpperCase();
          if (c0.includes(" DİLİMİ")) {
            currentDilim = row[0].trim();
            continue;
          }
          if (c0 === "UYGULAMA TARIHI" || c0 === "UYGULAMA TARİHİ") {
            headers = row.map(r => r.trim());
            continue;
          }
          
          const date = parseTurkishDate(row[0]);
          if (date && headers.length >= 3) {
             const baslama = row[1] || "";
             const tParts = baslama.split("-");
             let startT = null, endT = null;
             if (tParts.length === 2) {
                 startT = parseTime(tParts[0]);
                 endT = parseTime(tParts[1]);
             }
             if (!minDate || date < minDate) minDate = date;
             if (!maxDate || date > maxDate) maxDate = date;
             
             for (let c = 2; c < row.length; c++) {
                const val = (row[c] || "").trim();
                const title = headers[c];
                if (val && title && title.toUpperCase() !== "SAATİ" && title.toUpperCase() !== "SAAT") {
                   parsed.push({
                      date, startT, endT,
                      title, dilim: currentDilim,
                      groups: val,
                      konu: `${title} (Gruplar: ${val})`
                   });
                }
             }
          }
        }
        setEvents(parsed);
        setSemesterRange({ start: minDate, end: maxDate });
        setLoading(false);
      })
      .catch(e => { setError("Veri yüklenemedi: " + e.message); setLoading(false); });
  }, [userYear]);

  const filteredEvents = events.filter(evt => {
     if (filterGroup === "Tüm Gruplar") return true;
     const targetGroup = filterGroup.replace("Grup ", "").trim();
     const evtGroups = evt.groups.toUpperCase();
     return evtGroups.includes(targetGroup) || evtGroups.includes("TÜM GRUPLAR") || evtGroups.includes("TUM GRUPLAR");
  });

  const weekDays = [];
  for (let i = 0; i < 5; i++) {
    const d = new Date(weekStart);
    d.setDate(d.getDate() + i);
    weekDays.push(d);
  }

  const today = new Date();
  const todayMonday = getMonday(today);
  const isCurrentWeek = isSameDay(weekStart, todayMonday);

  let weekNum = null;
  if (semesterRange.start) {
    const semesterMonday = getMonday(semesterRange.start);
    const diff = Math.floor((weekStart - semesterMonday) / (7 * 24 * 60 * 60 * 1000));
    if (diff >= 0) weekNum = diff + 1;
  }

  function getEventsForDay(date) {
    const dayEvents = filteredEvents.filter(e => isSameDay(e.date, date));
    dayEvents.sort((a, b) => {
      if (!a.startT || !b.startT) return 0;
      return (a.startT.h * 60 + a.startT.m) - (b.startT.h * 60 + b.startT.m);
    });
    return dayEvents;
  }

  const prevWeek = () => { const d = new Date(weekStart); d.setDate(d.getDate() - 7); setWeekStart(d); };
  const nextWeek = () => { const d = new Date(weekStart); d.setDate(d.getDate() + 7); setWeekStart(d); };
  const goToday = () => setWeekStart(getMonday(new Date()));

  const formatRange = () => {
    const end = new Date(weekStart); end.setDate(end.getDate() + 4);
    if (weekStart.getMonth() === end.getMonth()) {
      return `${weekStart.getDate()} – ${end.getDate()} ${TR_MONTH_FULL[weekStart.getMonth()]} ${weekStart.getFullYear()}`;
    }
    return `${weekStart.getDate()} ${TR_MONTH_NAMES[weekStart.getMonth()]} – ${end.getDate()} ${TR_MONTH_NAMES[end.getMonth()]} ${end.getFullYear()}`;
  };

  if (loading) return (
    <div style={{ textAlign:"center", padding:60 }}>
      <div style={{ fontSize:32, marginBottom:16, animation:"spin 1s linear infinite" }}>⏳</div>
      <p style={{ color:"#94a3b8", fontSize:14 }}>Uygulama programı yükleniyor...</p>
    </div>
  );
  if (error) return (
    <div style={{ ...s.card, textAlign:"center", padding:40 }}>
      <div style={{ fontSize:40, marginBottom:12 }}>📭</div>
      <p style={{ color:"#f87171", fontSize:15, fontWeight:600 }}>{error}</p>
    </div>
  );

  return (
    <div>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:16, flexWrap:"wrap", gap:12 }}>
         <p style={{ ...s.title, marginBottom:0 }}>🧪 Uygulama Programı</p>
         <select 
            value={filterGroup} 
            onChange={e => setFilterGroup(e.target.value)}
            style={{ padding:"8px 16px", borderRadius:10, background:"rgba(16,24,44,0.7)", border:"1px solid rgba(148,163,184,0.1)", color:"#e8edf5", outline:"none", fontSize:14, fontWeight:600, cursor:"pointer" }}
         >
            <option value="Tüm Gruplar">Tüm Gruplar</option>
            {GROUPS.map(g => <option key={g} value={g}>{g}</option>)}
         </select>
      </div>

      <div style={{ ...s.card, display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:20, padding:"14px 20px", flexWrap:"wrap", gap:10 }}>
        <button onClick={prevWeek} style={{ ...s.btn(false), padding:"8px 14px", fontSize:18, lineHeight:1, cursor:"pointer" }} title="Önceki Hafta">◀</button>
        <div style={{ textAlign:"center", flex:1, minWidth:200 }}>
          <div style={{ fontSize:16, fontWeight:700, color:"#e8edf5" }}>{formatRange()}</div>
          {weekNum && <div style={{ fontSize:12, color:"#94a3b8", marginTop:2 }}>Hafta {weekNum}</div>}
        </div>
        <div style={{ display:"flex", gap:8 }}>
          {!isCurrentWeek && <button onClick={goToday} style={{ ...s.btn(true), padding:"8px 14px", fontSize:12 }}>Bugün</button>}
          <button onClick={nextWeek} style={{ ...s.btn(false), padding:"8px 14px", fontSize:18, lineHeight:1, cursor:"pointer" }} title="Sonraki Hafta">▶</button>
        </div>
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"repeat(5, 1fr)", gap:10 }}>
        {weekDays.map((day, di) => {
          const isToday = isSameDay(day, today);
          const dayEvents = getEventsForDay(day);
          return (
            <div key={di} style={{ minWidth:0 }}>
              <div style={{
                textAlign:"center", padding:"10px 4px", marginBottom:8, borderRadius:12,
                background: isToday ? "linear-gradient(135deg,rgba(0,212,170,0.2),rgba(0,184,148,0.1))" : "rgba(16,24,44,0.5)",
                border: isToday ? "1px solid rgba(0,212,170,0.4)" : "1px solid rgba(148,163,184,0.08)",
              }}>
                <div style={{ fontSize:13, fontWeight:600, color: isToday ? "#00d4aa" : "#94a3b8" }}>{TR_DAY_NAMES[day.getDay()]}</div>
                <div style={{ fontSize:20, fontWeight:700, color: isToday ? "#00d4aa" : "#e8edf5", lineHeight:1.3 }}>{day.getDate()}</div>
                <div style={{ fontSize:11, color: isToday ? "#00d4aa" : "#64748b" }}>{TR_MONTH_NAMES[day.getMonth()]}</div>
              </div>
              
              {dayEvents.length === 0 && (
                <div style={{ textAlign:"center", padding:"24px 8px", color:"#475569", fontSize:12, borderRadius:10, border:"1px dashed rgba(148,163,184,0.1)" }}>
                  Uygulama yok
                </div>
              )}
              
              {dayEvents.map((evt, ei) => {
                const color = getDilimColor(evt.dilim);
                const timeStr = evt.startT && evt.endT
                  ? `${String(evt.startT.h).padStart(2,"0")}:${String(evt.startT.m).padStart(2,"0")} – ${String(evt.endT.h).padStart(2,"0")}:${String(evt.endT.m).padStart(2,"0")}`
                  : "Tüm gün";
                  
                let dilimShort = evt.dilim || "";
                if (dilimShort.length > 22) dilimShort = dilimShort.substring(0, 20) + "…";
                
                return (
                  <div key={ei} onClick={() => setSelectedEvent({ ...evt, timeStr, color, dilimShort })} style={{
                    marginBottom:6, borderRadius:10, padding:"8px 10px",
                    background:"rgba(16,24,44,0.7)",
                    borderLeft:`3px solid ${color}`,
                    border:`1px solid rgba(148,163,184,0.08)`,
                    borderLeftWidth:3, borderLeftColor:color, borderLeftStyle:"solid",
                    transition:"all 0.2s ease",
                    cursor:"pointer",
                    fontSize:12,
                  }}>
                    <div style={{ color:"#64748b", fontSize:10, marginBottom:3, fontWeight:600 }}>{timeStr}</div>
                    <div style={{ fontWeight:600, color:"#e8edf5", fontSize:12, lineHeight:1.3, marginBottom:4, wordBreak:"break-word" }}>
                      {evt.title.length > 40 ? evt.title.substring(0, 38) + "…" : evt.title}
                    </div>
                    <div style={{ display:"inline-block", padding:"1px 7px", borderRadius:6, fontSize:9, fontWeight:700, background:"rgba(148,163,184,0.1)", color:"#94a3b8", marginBottom:3 }}>
                      Grup: {evt.groups}
                    </div>
                    {dilimShort && (
                      <div style={{ display:"block", marginTop:2, color:color, fontSize:9, fontWeight:700 }}>
                        {dilimShort}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>

      {selectedEvent && (
        <div onClick={() => setSelectedEvent(null)} style={{
          position:"fixed", inset:0, zIndex:9999,
          background:"rgba(0,0,0,0.7)", backdropFilter:"blur(6px)",
          display:"flex", alignItems:"center", justifyContent:"center", padding:20,
        }}>
          <div onClick={e => e.stopPropagation()} style={{
            background:"linear-gradient(145deg, #1a2340, #0f172a)",
            borderRadius:16, padding:24, maxWidth:420, width:"100%",
            border:`1px solid ${selectedEvent.color}33`,
            boxShadow:`0 20px 60px rgba(0,0,0,0.5), 0 0 40px ${selectedEvent.color}15`, position:"relative",
          }}>
            <button onClick={() => setSelectedEvent(null)} style={{
              position:"absolute", top:12, right:12, background:"rgba(148,163,184,0.1)",
              border:"none", color:"#94a3b8", fontSize:18, width:32, height:32,
              borderRadius:8, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center",
            }}>✕</button>

            <div style={{ color:selectedEvent.color, fontSize:14, fontWeight:600, marginBottom:12 }}>🕐 {selectedEvent.timeStr}</div>
            <div style={{ fontWeight:700, color:"#e8edf5", fontSize:18, lineHeight:1.4, marginBottom:16, paddingRight:30 }}>{selectedEvent.title}</div>
            <div style={{ marginBottom:12 }}>
                <div style={{ color:"#64748b", fontSize:11, marginBottom:4, textTransform:"uppercase", letterSpacing:1 }}>Giren Gruplar</div>
                <div style={{ color:"#e8edf5", fontSize:14 }}>👥 {selectedEvent.groups}</div>
            </div>
            {selectedEvent.dilim && (
              <div style={{ marginBottom:12 }}>
                <div style={{ color:"#64748b", fontSize:11, marginBottom:4, textTransform:"uppercase", letterSpacing:1 }}>Dilim</div>
                <div style={{
                  display:"inline-block", padding:"4px 12px", borderRadius:8, fontSize:13, fontWeight:700,
                  background:`${selectedEvent.color}22`, color:selectedEvent.color,
                }}>{selectedEvent.dilim}</div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

